from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares_with(xs: list[int], workers: int) -> int:
    """Sum of squares of xs, computing each square via square() in a
    thread pool of `workers` threads. The result is independent of
    `workers`. Raises ValueError if workers < 1."""
    if workers < 1:
        raise ValueError("workers must be >= 1")
    with ThreadPoolExecutor(max_workers=workers) as pool:
        squares = list(pool.map(square, xs))
    return sum(squares)


def sum_squares(xs: list[int]) -> int:
    """Sum of the squares of every element of xs (0 for an empty list),
    computed in parallel with a thread pool using a default worker count."""
    return sum_squares_with(xs, 4)


WORKER_COUNTS = [1, 2, 3, 4, 8, 16, 64]


def test_sum_squares_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14
    assert sum_squares([5]) == 25


def test_sum_squares_empty() -> None:
    assert sum_squares([]) == 0
    for w in WORKER_COUNTS:
        assert sum_squares_with([], w) == 0


def test_sum_squares_negatives_and_zero() -> None:
    assert sum_squares([-3, 0, 3]) == 18
    assert sum_squares([0, 0, 0]) == 0


def test_sum_squares_big_ints() -> None:
    big = 10**20
    assert sum_squares([big, -big]) == 2 * big * big


def test_same_result_at_every_worker_count() -> None:
    xs = list(range(-50, 51)) + [10**9, -(10**9), 7, 7]
    expected = sum(x * x for x in xs)
    for w in WORKER_COUNTS:
        assert sum_squares_with(xs, w) == expected
    assert sum_squares(xs) == expected


def test_more_workers_than_items() -> None:
    assert sum_squares_with([2, 3], 100) == 13
    assert sum_squares_with([4], 8) == 16


def test_does_not_mutate_input() -> None:
    xs = [3, -1, 2]
    sum_squares_with(xs, 4)
    assert xs == [3, -1, 2]


def test_invalid_worker_count() -> None:
    with pytest.raises(ValueError):
        sum_squares_with([1, 2, 3], 0)
    with pytest.raises(ValueError):
        sum_squares_with([1, 2, 3], -2)
